class Uint8Matrix {
    constructor(rows, cols, defaultValue) {
        const data = new Uint8Array(rows * cols);
        for (let i = 0, len = rows * cols; i < len; i++) {
            data[i] = defaultValue;
        }
        this.a = data;
        this.rows = rows;
        this.cols = cols;
    }
    get(row, col) {
        return this.a[row * this.cols + col];
    }
    set(row, col, value) {
        this.a[row * this.cols + col] = value;
    }
}
